"""Wire fixtures recovered from independent controlled website exports."""

import unittest

from czn_deckcode._serialization import deserialize, serialize
from czn_deckcode.errors import InvalidCodeError, InvalidDeckError
from czn_deckcode.models import Card, Deck


class SerializationTests(unittest.TestCase):
    def test_controlled_single_card_wire_fixtures(self):
        # These byte strings were recovered from website codes, rather than
        # generated by this serializer. They pin the optional-field wire order.
        fixtures = (
            ({}, "b6eb0101000c635f33303133345f73727431"),
            ({"removed": True}, "b6eb0101010c635f33303133345f73727431"),
            (
                {"duplicate": True},
                "b6eb0101040c635f33303133345f73727431"
                "011254414c454e545f5245504c49434154494f4e",
            ),
            (
                {"variant_card_id": "c_30134_srt1_pot"},
                "b6eb01010010635f33303133345f737274315f706f74",
            ),
            (
                {"variant_card_id": "c_30134_srt1_rsp1"},
                "b6eb0101020c635f33303133345f73727431"
                "0111727370315f635f33303133345f73727431",
            ),
            (
                {"epiphany_id": "c03014"},
                "b6eb0101020c635f33303133345f737274310306633033303134",
            ),
            (
                {"epiphany_id": "c00001", "divine_id": "add_r_spark_vitor_01"},
                "b6eb0101420c635f33303133345f737274310306633030303031"
                "146164645f725f737061726b5f7669746f725f3031",
            ),
            (
                {"epiphany_id": "c_30047_05013"},
                "b6eb0101020c635f33303133345f73727431"
                "030d635f33303034375f3035303133",
            ),
            (
                {"epiphany_id": "c00001", "divine_id": "assault_r_spark_secred_4_0"},
                "b6eb0101420c635f33303133345f737274310306633030303031"
                "1a61737361756c745f725f737061726b5f7365637265645f345f30",
            ),
        )
        for fields, expected in fixtures:
            with self.subTest(fields=fields):
                payload = bytes.fromhex(expected)
                self.assertEqual(serialize(Deck("30134", (Card("c_30134_srt1", **fields),))), payload)
                self.assertEqual(serialize(deserialize(payload)), payload)

    def test_all_optional_fields_and_lossy_site_normalization(self):
        deck = Deck("30134", (Card(
            "c_30134_srt1", removed=True, duplicate=True,
            variant_card_id="c_30134_srt1_rsp2", epiphany_id="c00001",
            divine_id="add_r_spark_vitor_01", god="circen",
        ),))
        expected = bytes.fromhex(
            "b6eb0101470c635f33303133345f73727431"
            "0111727370325f635f33303133345f73727431"
            "146164645f725f737061726b5f7669746f725f3031"
            "011254414c454e545f5245504c49434154494f4e"
        )
        self.assertEqual(serialize(deck), expected)
        self.assertEqual(deserialize(expected), Deck("30134", (Card(
            "c_30134_srt1", removed=True, duplicate=True,
            variant_card_id="c_30134_srt1_rsp2",
            divine_id="add_r_spark_vitor_01", god="VITOR",
        ),)))

    def test_pot_and_lbk_are_stored_as_effective_card_id(self):
        for suffix in ("pot", "lbk"):
            with self.subTest(suffix=suffix):
                variant = f"c_30134_srt1_{suffix}"
                original = Deck("30134", (Card("c_30134_srt1", variant_card_id=variant),))
                self.assertEqual(deserialize(serialize(original)), Deck("30134", (Card(variant),)))

    def test_unknown_variant_is_ignored_and_rsp_takes_epiphany_precedence(self):
        plain = Deck("30134", (Card("c_30134_srt1"),))
        ignored = Deck("30134", (Card("c_30134_srt1", variant_card_id="unknown", god="NYX"),))
        self.assertEqual(serialize(plain), serialize(ignored))
        rsp = Deck("30134", (Card("c_30134_srt1", variant_card_id="c_999_srt1_rsp1", epiphany_id="ignored"),))
        self.assertEqual(deserialize(serialize(rsp)).cards[0].variant_card_id, "c_999_srt1_rsp1")

    def test_card_order_and_multiple_removed_or_duplicate_cards_are_preserved(self):
        deck = Deck("30134", (
            Card("c_30134_uni4", duplicate=True), Card("c_30134_srt2", removed=True),
            Card("c_30134_uni1", duplicate=True), Card("card_future_1"),
        ))
        self.assertEqual(deserialize(serialize(deck)), deck)

    def test_uint32_boundaries_and_unrepresentable_character_ids(self):
        for char_id, encoded in (("0", "0000"), ("127", "7f00"), ("128", "800100"), ("4294967295", "ffffffff0f00")):
            with self.subTest(char_id=char_id):
                payload = bytes.fromhex(encoded)
                self.assertEqual(serialize(Deck(char_id, ())), payload)
                self.assertEqual(deserialize(payload), Deck(char_id, ()))
        for char_id in ("-1", "001", "00", "4294967296", "future-character"):
            with self.subTest(char_id=char_id), self.assertRaises(InvalidDeckError):
                serialize(Deck(char_id, ()))

    def test_invalid_builder_state_is_rejected_before_encoding(self):
        for card in (
            Card("c_999_srt1"), Card("invalid"),
            Card("c_30134_srt1", epiphany_id="unknown"),
            Card("c_30134_srt1", divine_id="add_r_spark_vitor_01"),
            Card("c_30134_srt1", epiphany_id="c1", divine_id="unknown"),
            Card("c_30134_srt1", variant_card_id="INVALID_rsp1"),
            Card("c_30134_" + "a" * 256),
        ):
            with self.subTest(card=card), self.assertRaisesRegex(InvalidDeckError, r"cards\[0\]"):
                serialize(Deck("30134", (card,)))

    def test_truncations_and_unrecognized_fields_do_not_silently_drop_data(self):
        valid = serialize(Deck("30134", (Card(
            "c_30134_srt1", removed=True, duplicate=True, epiphany_id="c1",
            divine_id="add_r_spark_vitor_01",
        ),)))
        for end in range(len(valid)):
            with self.subTest(end=end), self.assertRaises(InvalidCodeError):
                deserialize(valid[:end])
        invalid = (
            valid + b"\x00",  # trailing data
            b"\x80\x00\x00",  # overlong integer
            b"\xff\xff\xff\xff\x10\x00",  # uint32 overflow
            b"\x00\xff\xff\xff\xff\x0f",  # impossible card count
            b"\x00\x01\x08\x03p_a",  # unsupported flags
            b"\x00\x01\x00\x00\x00",  # empty ID
            b"\x00\x01\x00\x01\xff",  # malformed UTF-8
            b"\x00\x01\x02\x03p_a\x02\x02c1",  # unsupported category
            b"\x00\x01\x02\x03p_a\x01\x02c1",  # malformed rsp field
            b"\x00\x01\x40\x03p_a\x01x",  # divine without epiphany
            b"\x00\x01\x04\x03p_a\x01\x01x",  # unknown talent
            b"\x00\x01\x04\x03p_a\x02\x01x\x01y",  # multiple talents
        )
        for payload in invalid:
            with self.subTest(payload=payload.hex()), self.assertRaises(InvalidCodeError):
                deserialize(payload)


if __name__ == "__main__":
    unittest.main()
